import fs from 'fs'
import os from 'os'
import path from 'path'
import { runInNewContext } from 'vm'
import {
  afterAll,
  afterEach,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
} from 'vitest'
import { Mode } from '../../../src/constants'
import generator from '../../../src/generator'
import * as ts from 'typescript'

import {
  loadFixture,
  mkdtemp,
  readFile,
  replaceSpacesAndNewLineToSingleSpace,
  rmdir,
  writeFile,
} from '../helper'

const commonSubstringsForAllSDK = [
  'Automatically generated by',
  'Do not edit manually',
  'Service version',
  'const mergedRequestParameters = this._mergeRequestParameters( requestParameters || {}, this.commonRequestParameters, );',
  'try { data = response.json(); } catch { data = response.body; }',
]

const commonMatchesForAllSDK = [
  /return { response, data, operationId: "[^"]*", };/,
]

const commonSubstringsForK6SampleScript = [`const baseUrl = "<BASE_URL>";`]

function loadGeneratedClient(
  source: string,
  request: (...args: unknown[]) => unknown
) {
  const compiled = ts.transpileModule(source, {
    compilerOptions: {
      esModuleInterop: true,
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
    },
  })
  const generatedModule = { exports: {} as Record<string, unknown> }

  runInNewContext(compiled.outputText, {
    exports: generatedModule.exports,
    module: generatedModule,
    require: (name: string) => {
      if (name === 'k6/http') {
        return { request }
      }
      throw new Error(`Unexpected generated-client import: ${name}`)
    },
  })

  return generatedModule.exports
}

describe('generator', () => {
  let tempDir: string, schemaDirectory: string
  const allFixtures = fs.readdirSync(path.join(__dirname, 'fixtures'))

  beforeAll(async () => {
    tempDir = await mkdtemp(path.join(os.tmpdir(), 'sdk-generator-'))
  })

  afterAll(async () => {
    await rmdir(tempDir, { recursive: true })
  })

  for (const fixtureName of allFixtures) {
    describe(`test ${fixtureName} OpenAPI schema`, () => {
      let openApiPath: string, generatedSchemaPath: string
      const fixture = loadFixture(path.join(__dirname, 'fixtures', fixtureName))

      beforeEach(async () => {
        schemaDirectory = await mkdtemp(
          path.join(tempDir, fixtureName.replace('.', '-'))
        )
        // Write the OpenAPI schema to a file

        openApiPath = path.join(schemaDirectory, 'openapi-schema.json')

        await writeFile(openApiPath, JSON.stringify(fixture['openapi_schema']))

        generatedSchemaPath = path.join(schemaDirectory, 'generated-schema')
      })

      afterEach(async () => {
        await rmdir(schemaDirectory, { recursive: true })
      })

      it(`should generate SDK client from the OpenAPI schema`, async () => {
        const expectedGeneratedCode = fixture['expected_sdk']

        await generator({
          openApiPath,
          outputDir: generatedSchemaPath,
          mode: Mode.SINGLE,
        })

        const generatedFiles = fs.readdirSync(generatedSchemaPath)
        expect(generatedFiles.length).toBe(1)
        expect(generatedFiles[0]).toBeDefined()
        const fileName = path.basename(generatedFiles[0]!)
        expect(fileName).toBe(expectedGeneratedCode.fileName)
        const generatedFilePath = path.join(
          generatedSchemaPath,
          generatedFiles[0]!
        )
        const generatedContent = await readFile(generatedFilePath, 'utf-8')

        for (const expectedString of [
          ...expectedGeneratedCode['expectedSubstrings'],
          ...commonSubstringsForAllSDK,
        ]) {
          expect(
            replaceSpacesAndNewLineToSingleSpace(generatedContent)
          ).toContain(expectedString)
        }
        for (const expectedToMatch of commonMatchesForAllSDK) {
          expect(
            replaceSpacesAndNewLineToSingleSpace(generatedContent)
          ).toMatch(expectedToMatch)
        }
      })

      it('should generate a sample K6 script', async () => {
        await generator({
          openApiPath,
          outputDir: generatedSchemaPath,
          shouldGenerateSampleK6Script: true,
          mode: Mode.SINGLE,
        })

        const generatedFiles = fs.readdirSync(generatedSchemaPath)
        expect(generatedFiles.length).toBe(2)
        const k6ScriptFile = generatedFiles.find((file) =>
          file.includes('k6-script')
        )
        expect(k6ScriptFile).toBeDefined()
        expect(k6ScriptFile).toBe('k6-script.sample.ts')

        const generatedFilePath = path.join(generatedSchemaPath, k6ScriptFile!)
        const generatedContent = await readFile(generatedFilePath, 'utf-8')

        for (const expectedString of [...commonSubstringsForK6SampleScript]) {
          expect(generatedContent).toContain(expectedString)
        }
      })

      it('should not contain types in main file when using split mode', async () => {
        await generator({
          openApiPath,
          outputDir: generatedSchemaPath,
          shouldGenerateSampleK6Script: true,
          mode: Mode.SPLIT,
        })
        const expectedGeneratedCode = fixture['expected_sdk']
        const generatedFiles = fs.readdirSync(generatedSchemaPath)

        expect(generatedFiles.length).toBe(3)

        const clientFile = generatedFiles.find((file) =>
          file.includes(expectedGeneratedCode.fileName)
        )
        const schemaFile = generatedFiles.find((file) =>
          file.includes('.schemas.ts')
        )

        expect(clientFile).toBeDefined()
        expect(schemaFile).toBeDefined()

        const generatedFilePath = path.join(generatedSchemaPath, clientFile!)
        const generatedContent = await readFile(generatedFilePath, 'utf-8')

        expect(generatedContent).not.toContain('export type')
        expect(generatedContent).not.toContain('export interface')
      })
    })
  }

  it('does not import the URL polyfill into generated clients', async () => {
    const fixture = loadFixture(
      path.join(__dirname, 'fixtures', 'query_params_schema.json')
    )
    fixture['openapi_schema'].paths['/example'].get.parameters[0].required =
      false
    const schemaDirectory = await mkdtemp(
      path.join(tempDir, 'url-polyfill-regression-')
    )
    const openApiPath = path.join(schemaDirectory, 'openapi-schema.json')
    const outputDir = path.join(schemaDirectory, 'generated')

    try {
      await writeFile(openApiPath, JSON.stringify(fixture['openapi_schema']))
      await generator({
        openApiPath,
        outputDir,
        mode: Mode.SINGLE,
      })

      const generatedFile = fs.readdirSync(outputDir)[0]
      expect(generatedFile).toBeDefined()
      const generatedContent = await readFile(
        path.join(outputDir, generatedFile!),
        'utf-8'
      )

      expect(generatedContent).not.toContain(
        'https://jslib.k6.io/url/1.0.0/index.js'
      )

      const requestedUrls: string[] = []
      const generatedModule = loadGeneratedClient(
        generatedContent,
        (...args) => {
          if (typeof args[1] !== 'string') {
            throw new Error('The generated request URL must be a string')
          }
          requestedUrls.push(args[1])
          return { json: () => ({}), body: '' }
        }
      )
      const ExampleAPIClient =
        generatedModule.ExampleAPIClient as new (options: {
          baseUrl: string
        }) => {
          getExampleData: (params?: Record<string, unknown>) => unknown
        }
      const client = new ExampleAPIClient({
        baseUrl: 'https://api.example.test/v1/',
      })
      const params = {
        name: "a b!~*'() café 😀",
        age: 42,
        isActive: false,
        tags: ['one two', 'x&y'],
        date: '\ud800',
      }

      client.getExampleData(params)
      client.getExampleData()

      const search = new URLSearchParams(
        params as unknown as Record<string, string>
      ).toString()
      expect(requestedUrls).toEqual([
        `https://api.example.test/v1/example?${search}`,
        `https://api.example.test/v1/example?`,
      ])
    } finally {
      await rmdir(schemaDirectory, { recursive: true })
    }
  })

  it('encodes path values in generated URLs without the URL polyfill', async () => {
    const fixture = loadFixture(
      path.join(
        __dirname,
        'fixtures',
        'get_request_with_path_parameters_schema.json'
      )
    )
    const schemaDirectory = await mkdtemp(
      path.join(tempDir, 'path-url-encoding-')
    )
    const openApiPath = path.join(schemaDirectory, 'openapi-schema.json')
    const outputDir = path.join(schemaDirectory, 'generated')

    try {
      await writeFile(openApiPath, JSON.stringify(fixture['openapi_schema']))
      await generator({
        openApiPath,
        outputDir,
        mode: Mode.SINGLE,
      })

      const generatedFile = fs.readdirSync(outputDir)[0]
      expect(generatedFile).toBeDefined()
      const generatedContent = await readFile(
        path.join(outputDir, generatedFile!),
        'utf-8'
      )
      expect(generatedContent).not.toContain('__k6SerializeQueryParams')
      const requestedUrls: string[] = []
      const generatedModule = loadGeneratedClient(
        generatedContent,
        (...args) => {
          if (typeof args[1] !== 'string') {
            throw new Error('The generated request URL must be a string')
          }
          requestedUrls.push(args[1])
          return { json: () => ({}), body: '' }
        }
      )
      const SimpleAPIClient = generatedModule.SimpleAPIClient as new (options: {
        baseUrl: string
      }) => {
        getItemById: (id: string) => unknown
      }
      const client = new SimpleAPIClient({
        baseUrl: 'https://api.example.test/v1/',
      })

      client.getItemById('a b/é')
      const unusualPathValue = `${String.fromCharCode(0xd83d, 0xde00)} ${String.fromCharCode(0xd800)} ${String.fromCharCode(0xdc00)}`
      client.getItemById(unusualPathValue)

      expect(requestedUrls).toEqual([
        new URL('https://api.example.test/v1/items/a b/é').toString(),
        new URL(
          `https://api.example.test/v1/items/${unusualPathValue}`
        ).toString(),
      ])
    } finally {
      await rmdir(schemaDirectory, { recursive: true })
    }
  })

  it('preserves valid percent escapes without decoding path delimiters', async () => {
    const fixture = loadFixture(
      path.join(
        __dirname,
        'fixtures',
        'get_request_with_path_parameters_schema.json'
      )
    )
    const schema = fixture['openapi_schema']
    schema.paths['/escaped%20path/%2F'] = {
      get: {
        operationId: 'getEscapedPath',
        responses: { '200': { description: 'OK' } },
      },
    }
    const schemaDirectory = await mkdtemp(path.join(tempDir, 'escaped-path-'))
    const openApiPath = path.join(schemaDirectory, 'schema.json')
    const outputDir = path.join(schemaDirectory, 'generated')
    try {
      await writeFile(openApiPath, JSON.stringify(schema))
      await generator({ openApiPath, outputDir, mode: Mode.SINGLE })
      const [generatedFile] = fs.readdirSync(outputDir)
      const source = await readFile(
        path.join(outputDir, generatedFile!),
        'utf-8'
      )
      const requestedUrls: string[] = []
      const generatedModule = loadGeneratedClient(source, (...args) => {
        requestedUrls.push(String(args[1]))
        return { json: () => ({}), body: '' }
      })
      const SimpleAPIClient = generatedModule.SimpleAPIClient as new (options: {
        baseUrl: string
      }) => {
        getItemById: (id: string) => unknown
        getEscapedPath: () => unknown
      }
      const client = new SimpleAPIClient({
        baseUrl: 'https://api.example.test/v1/',
      })
      const cases: [string, string][] = [
        ['a%20b', 'a%20b'],
        ['a%2Fb', 'a%2Fb'],
        ['%C3%A9', '%C3%A9'],
        ['%c3%a9', '%c3%a9'],
        ['%3Fadmin%3Dtrue', '%3Fadmin%3Dtrue'],
        ['%23fragment', '%23fragment'],
        ['%252F', '%252F'],
        ['%25', '%25'],
        ['%00%0d%0a', '%00%0d%0a'],
        ['a b/é', 'a%20b/%C3%A9'],
        ['100%', '100%25'],
        ['%2', '%252'],
        ['%GG', '%25GG'],
        ['%%20', '%25%20'],
        ['😀', '%F0%9F%98%80'],
        ['\ud800', '%EF%BF%BD'],
      ]
      for (const [input, expected] of cases) {
        client.getItemById(input)
        expect(requestedUrls.at(-1)).toBe(
          `https://api.example.test/v1/items/${expected}`
        )
      }
      client.getEscapedPath()
      expect(requestedUrls.at(-1)).toBe(
        'https://api.example.test/v1/escaped%20path/%2F'
      )
    } finally {
      await rmdir(schemaDirectory, { recursive: true })
    }
  })
})
